BEGIN;
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000001',true);
CREATE TEMP TABLE chat_before AS SELECT id,to_jsonb(w)-'chat_source_link' AS original FROM public.paige_durable_work w;
CREATE TEMP TABLE turns_before AS SELECT count(*) AS total FROM public.paige_chat_turns;
CREATE TEMP TABLE turn_work_before AS SELECT id,work_id FROM public.paige_chat_turns;
CREATE TEMP TABLE thread_count_before AS SELECT count(*) total FROM public.paige_chat_threads;
SET LOCAL ROLE authenticated;
SELECT public.test_assert(public.test_chat_inspect()='{"status":"absent_at_read"}','host link absent before explicit Save');
SELECT public.test_denied($q$SELECT public.test_chat_save(NULL,0,repeat('a',64))$q$,'CHAT_KNOWLEDGE_SOURCE_CHANGED');
SELECT public.test_assert(public.test_chat_inspect()='{"status":"absent_at_read"}','wrong source bytes cannot persist a reference');
SELECT public.test_assert(public.test_chat_save()#>>'{reference,turnId}' IS NULL,'staged attachment saves honestly without a fabricated message');
SELECT public.test_assert(public.test_chat_inspect()#>>'{reference,linkRevision}'='1','native authoritative readback preserves first host CAS');
SELECT public.test_assert(public.test_chat_inspect()#>>'{reference,publicationWorkId}'=public.test_chat_work()::text,'receipt identifies the actual original publication work');
SELECT public.test_assert(public.test_chat_inspect()#>>'{reference,generationId}'=public.test_chat_work()::text,'receipt identifies the canonical promoted generation');
SELECT public.test_assert(public.test_chat_inspect()#>>'{reference,extractionIntentId}'='70000000-0000-4000-8000-000000000080','original extraction intent survives publication');
SELECT public.test_assert(public.test_chat_inspect()#>>'{reference,publicationIntentId}'='60000000-0000-4000-8000-000000000080','publication intent is independently server resolved');
SELECT public.test_assert(public.test_chat_save()=public.test_chat_inspect(),'lost host acknowledgment reconciles same native identity without another effect');
SELECT public.test_assert(public.list_paige_chat_knowledge_links('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001')#>>'{items,0,reference,publicationWorkId}'=public.test_chat_work()::text,'reload discovers the actual original thread work reference');
SELECT public.test_denied($q$SELECT public.test_chat_save('80000000-0000-4000-8000-000000000001',0)$q$,'CHAT_KNOWLEDGE_LINK_CONFLICT');
SELECT public.test_denied($q$SELECT public.test_chat_save('80000000-0000-4000-8000-000000000002',1)$q$,'CHAT_KNOWLEDGE_MESSAGE_UNAVAILABLE');
SELECT public.test_denied($q$SELECT public.test_chat_save('80000000-0000-4000-8000-000000000003',1)$q$,'CHAT_KNOWLEDGE_MESSAGE_UNAVAILABLE');
SELECT public.test_assert(public.test_chat_save('80000000-0000-4000-8000-000000000001',1)#>>'{reference,linkRevision}'='2','explicit real user message adoption advances original host CAS once');
SELECT public.test_assert(public.test_chat_save('80000000-0000-4000-8000-000000000001',1)=public.test_chat_inspect(),'same real message replay returns same authoritative reference');
SELECT public.test_denied($q$SELECT public.test_chat_save(NULL,1)$q$,'CHAT_KNOWLEDGE_LINK_CONFLICT');
RESET ROLE;
SELECT public.test_assert((SELECT count(*)=(SELECT total FROM turns_before) FROM public.paige_chat_turns),'no synthetic user/assistant/system message was appended');
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.paige_chat_turns t FULL JOIN turn_work_before b USING(id) WHERE t.id IS NULL OR b.id IS NULL OR t.work_id IS DISTINCT FROM b.work_id),'all original message Work bindings remain exact');
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.paige_durable_work w FULL JOIN chat_before b USING(id) WHERE b.id IS NULL OR w.id IS NULL OR to_jsonb(w)-'chat_source_link' IS DISTINCT FROM b.original),'all original Work execution/receipt/authority/version/payload fields and row identities remain exact');
SELECT public.test_assert((SELECT bundle_ref->>'incumbent'='preserved' AND bundle_ref->'paige_record_links' @> jsonb_build_array(jsonb_build_object('destination','business_knowledge','record_id',(SELECT result->>'document_id' FROM public.extract_test WHERE name='chat'))) FROM public.paige_chat_turns WHERE id='80000000-0000-4000-8000-000000000001'),'original message metadata preserved with reference-only internal Knowledge target');
SAVEPOINT corrupt_annotation;
UPDATE public.paige_durable_work SET chat_source_link=jsonb_set(chat_source_link,'{schemaVersion}','2') WHERE id=public.test_chat_work();
SET LOCAL ROLE authenticated;
SELECT public.test_denied('SELECT public.test_chat_inspect()','CHAT_KNOWLEDGE_LINK_CONFLICT');
ROLLBACK TO SAVEPOINT corrupt_annotation;
SAVEPOINT corrupt_message;
UPDATE public.paige_chat_turns SET bundle_ref='{}' WHERE id='80000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT public.test_assert(public.test_chat_inspect()=' {"status":"recorded","current":false,"reason":"message_unavailable_or_changed"}'::jsonb,'removed presentation reference never erases native source identity or invents a current message');
ROLLBACK TO SAVEPOINT corrupt_message;
SAVEPOINT source_change;
UPDATE public.tenant_knowledge_docs SET summary='Changed metadata' WHERE id=(SELECT (result->>'document_id')::uuid FROM public.extract_test WHERE name='chat');
SET LOCAL ROLE authenticated;
SELECT public.test_assert(public.test_chat_inspect()='{"status":"recorded","current":false,"reason":"source_unavailable_or_changed"}','changed revision masks source details without resubmitting');
SELECT public.test_denied($q$SELECT public.test_chat_save('80000000-0000-4000-8000-000000000001',1)$q$,'CHAT_KNOWLEDGE_SOURCE_CHANGED');
ROLLBACK TO SAVEPOINT source_change;
SAVEPOINT switched;
UPDATE public.profiles SET active_tenant_id='00000000-0000-0000-0000-000000000002' WHERE user_id='10000000-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT public.test_denied('SELECT public.test_chat_inspect()','CHAT_KNOWLEDGE_SCOPE_CHANGED');
ROLLBACK TO SAVEPOINT switched;
SAVEPOINT revoked;
UPDATE public.tenant_members SET status='inactive' WHERE user_id='10000000-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT public.test_denied('SELECT public.test_chat_inspect()','CHAT_KNOWLEDGE_SCOPE_CHANGED');
ROLLBACK TO SAVEPOINT revoked;
SAVEPOINT archived;
UPDATE public.paige_chat_threads SET is_archived=true WHERE id='50000000-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT public.test_denied('SELECT public.test_chat_inspect()','CHAT_KNOWLEDGE_THREAD_UNAVAILABLE');
ROLLBACK TO SAVEPOINT archived;
SAVEPOINT private_thread;
UPDATE public.paige_chat_threads SET audience='customer_private' WHERE id='50000000-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT public.test_denied('SELECT public.test_chat_inspect()','CHAT_KNOWLEDGE_THREAD_UNAVAILABLE');
ROLLBACK TO SAVEPOINT private_thread;
SAVEPOINT binary_source;
SET LOCAL ROLE authenticated;
SELECT public.test_denied($q$SELECT public.test_chat_binary_save(encode(sha256(convert_to('A reviewed binary agreement.','UTF8')),'hex'))$q$,'CHAT_KNOWLEDGE_SOURCE_CHANGED');
SELECT public.test_assert(public.test_chat_binary_save()#>>'{reference,sourceSha256}'=public.test_binary_binding()->>'sha256','native binary host reference binds raw-file SHA instead of edited text SHA');
SELECT public.test_assert(public.test_chat_binary_save()#>>'{reference,textSha256}'=encode(sha256(convert_to('A reviewed binary agreement.','UTF8')),'hex'),'binary reference independently retains actual reviewed canonical text hash');
SELECT public.test_assert(public.test_chat_binary_save()#>>'{reference,sourceSha256}'<>public.test_chat_binary_save()#>>'{reference,textSha256}','raw file and text identities remain explicitly distinct');
ROLLBACK TO SAVEPOINT binary_source;
SAVEPOINT first_value_thread;
SET LOCAL ROLE authenticated;
SELECT public.test_assert(public.test_chat_binary_save(NULL,NULL)#>>'{reference,turnId}' IS NULL,'brand-new Chat creates no fabricated message');
SELECT public.test_assert(public.test_chat_binary_save(NULL,NULL)#>>'{reference,threadId}' IS NOT NULL,'first-value source Save calls the actual original thread constructor');
SELECT public.test_assert(public.inspect_paige_chat_knowledge_link('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',NULL,
 (SELECT (started#>>'{publication,work_id}')::uuid FROM public.extract_test WHERE name='chat-binary'))=public.test_chat_binary_save(NULL,NULL),'UNKNOWN conversation creation reconciles same original source/work without another thread');
RESET ROLE;
SELECT public.test_assert((SELECT count(*)=(SELECT total+1 FROM thread_count_before) FROM public.paige_chat_threads),'replayed first-value Save creates exactly one actual conversation');
ROLLBACK TO SAVEPOINT first_value_thread;
SAVEPOINT intake_lifetime;
SET LOCAL ROLE authenticated;
SELECT public.test_assert(public.test_chat_stage()#>>'{reference,phase}'='intake','original extraction admission is durably linked BEFORE review or publication');
SELECT public.test_assert(public.test_chat_stage()->>'extractionStatus'='claimed','actual claimed status never becomes completed extraction or publication');
SELECT public.test_assert(NOT (public.test_chat_stage()->'reference') ? 'publicationWorkId'
 AND NOT (public.test_chat_stage()->'reference') ? 'publicationOutcome','admission reference invents neither publication identity nor receipt');
SELECT public.test_assert(public.test_chat_stage()->>'currentDocumentRevision'='1','pending source returns actual native document revision');
SELECT public.test_assert(jsonb_array_length(public.list_paige_chat_knowledge_links('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001')->'items')=2,'reload includes the original unpublished admission alongside a different published document');
RESET ROLE;
SET LOCAL ROLE service_role;
UPDATE public.extract_test SET started=public.start_knowledge_extraction((result->>'work_id')::uuid) WHERE name='chat-pending';
SELECT public.complete_knowledge_extraction((result->>'work_id')::uuid,started->>'server_key',1,1,'Pending original source',started->>'input_hash') FROM public.extract_test WHERE name='chat-pending';
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT public.test_assert(public.test_chat_stage()->>'extractionStatus'='succeeded' AND public.test_chat_stage()->>'currentDocumentRevision'='2','normal extraction advances current review revision without repeating intake');
SELECT public.test_assert(public.test_chat_stage()#>>'{reference,documentRevision}'='1' AND public.test_chat_stage()#>>'{reference,linkRevision}'='1','original admission receipt remains immutable across native extraction completion');
ROLLBACK TO SAVEPOINT intake_lifetime;
SAVEPOINT intake_to_publication;
SET LOCAL ROLE authenticated;
SELECT public.test_assert(public.test_chat_stage('chat')#>>'{reference,phase}'='intake','same original extraction identity can be reconciled after a publication acknowledgment was lost');
SELECT public.test_assert(jsonb_array_length(public.list_paige_chat_knowledge_links('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001')->'items')=1,'canonical saved publication reference suppresses its own admission alias on reload');
ROLLBACK TO SAVEPOINT intake_to_publication;
SET LOCAL ROLE authenticated;
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000004',true);
SELECT public.test_denied('SELECT public.test_chat_inspect()','CHAT_KNOWLEDGE_SCOPE_CHANGED');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT public.test_denied('SELECT public.inspect_paige_chat_knowledge_link(NULL,NULL,NULL,NULL)','permission denied');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT public.test_denied('SELECT public.inspect_paige_chat_knowledge_link(NULL,NULL,NULL,NULL)','permission denied');
RESET ROLE;
ROLLBACK;
